  "ref-ag-doc-version": "Versione",
  "ref-ag-doc-activated": "Attivato",
  "ref-ag-s1-title": "1. Parti e oggetto",
  "ref-ag-s1-body": "Il presente contratto stabilisce la collaborazione tra la società che gestisce questa piattaforma e te in qualità di partner segnalatore: presenti aziende clienti e opportunità di business e maturi una provvigione sugli affari conclusi con le aziende che segnali.",
  "ref-ag-s2-title": "2. Il tuo ruolo di partner segnalatore",
  "ref-ag-s2-l1": "Presenti aziende clienti e opportunità di business che rappresenti o con cui hai un rapporto reale.",
  "ref-ag-s2-l2": "Confermi di essere libero di presentare queste aziende e che ciò non violi alcun obbligo verso terzi.",
  "ref-ag-s2-l3": "L’azienda che presenti resta una tua segnalazione: gli affari conclusi con essa maturano la tua provvigione alle condizioni indicate di seguito.",
  "ref-ag-s3-title": "3. Provvigione",
  "ref-ag-s3-body": "Per gli affari conclusi con le aziende che segnali maturi una provvigione alle seguenti condizioni:",
  "ref-ag-s4-title": "4. Condizioni di pagamento",
  "ref-ag-s4-body": "La provvigione diventa esigibile quando l’affare segnalato risulta concluso, tutti i documenti richiesti sono stati forniti e la provvigione è stata approvata. I pagamenti vengono effettuati sul conto bancario che indichi nella sezione Dati di pagamento.",
  "ref-ag-s5-title": "5. Riservatezza",
  "ref-ag-s5-body": "I termini del presente contratto, l’identità delle aziende segnalate e tutte le informazioni commerciali scambiate sono riservati e non possono essere divulgati a terzi.",
  "ref-ag-s6-title": "6. Durata e modifiche",
  "ref-ag-s6-body": "Il contratto si applica dall’accettazione fino alla rescissione comunicata per iscritto. Quando i termini cambiano, viene emessa una nuova versione ed è richiesta la tua nuova accettazione; l’accettazione precedente resta registrata.",
