  "refa-cancel-title": "Annullare questa provvigione?",
  "refa-cancel-body": "La voce verrà contrassegnata come annullata e resterà visibile al partner come annullata. L’operazione non può essere annullata (al suo posto dovrà essere creata una nuova voce).",
  "refa-ag-dialog-title": "Contratto di segnalazione",
  "refa-ag-dialog-desc": "Definisci le condizioni della provvigione che il partner firmerà. Attiva il contratto per renderlo visibile nel suo portale per la firma.",
  "refa-ag-currency": "Valuta della provvigione",
  "refa-ag-conditions-ph": "Clausole speciali aggiunte al testo standard del contratto (facoltativo)",
  "refa-ag-resign-note": "Questo contratto è già firmato. La riattivazione con termini modificati incrementa la versione e il partner dovrà firmare di nuovo; l’accettazione precedente resta registrata.",
  "refa-ag-save-draft": "Salva (bozza)",
  "refa-ag-activate": "Salva e attiva per la firma",
  "refa-ag-reactivate": "Salva e riattiva (nuova versione)",
  "refa-ag-activated-toast": "Contratto attivato — il partner è stato avvisato di firmare.",
  "refa-ag-saved-toast": "Contratto salvato.",
  "misc-refresh": "Aggiorna",
  "marketplace-kyc-verified": "KYC verificato",
  "marketplace-kyc-not-verified": "KYC non verificato",
  "marketplace-dd-banner-title": "Fai affari in sicurezza — esegui la tua due diligence",
  "marketplace-dd-banner-short": "VELOS è un punto d’incontro neutrale che mette in contatto acquirenti e venditori. Non siamo parte di alcuna transazione, non gestiamo merce o fondi e non accettiamo alcuna responsabilità per gli affari conclusi tra i membri.",
  "marketplace-dd-banner-full": "Prima di impegnarti: verifica la registrazione e la reputazione della controparte, controlla licenze e certificati, insisti su un pagamento sicuro (deposito a garanzia o lettera di credito) e assicurati che lo scambio sia conforme alle leggi a te applicabili.",
  "marketplace-dd-open-safety": "Guida a sicurezza e conformità",
  "marketplace-dd-show-more": "Mostra di più",
  "marketplace-dd-show-less": "Mostra meno",
  "marketplace-dd-panel-title": "Sicurezza e conformità",
  "marketplace-dd-panel-subtitle": "Indicazioni pratiche di due diligence che ogni membro del marketplace dovrebbe seguire prima di inviare denaro o merce.",
  "marketplace-dd-panel-liability": "VELOS fornisce soltanto presentazioni e strumenti. Non siamo parte di alcun contratto, non custodiamo né movimentiamo merce o fondi, non certifichiamo la legalità di alcun annuncio e non accettiamo alcuna responsabilità per perdite derivanti da una transazione tra membri. Esegui sempre la tua due diligence e i tuoi controlli di conformità.",
  "marketplace-dd-s1-title": "1. Verifica la controparte",
  "marketplace-dd-s1-body": "Controlla il numero di registrazione aziendale, lo stato VAT/EORI e l’indirizzo fisico tramite i registri ufficiali. Su VELOS, prediligi i partner con il badge KYC verificato — la loro identità e i loro documenti sono stati esaminati — e leggi le recensioni degli affari passati. Una telefonata e un video dei locali sono un’assicurazione a costo minimo.",
  "marketplace-dd-s2-title": "2. Metti in sicurezza il pagamento",
  "marketplace-dd-s2-body": "Per le nuove controparti usa il deposito a garanzia (escrow) o una lettera di credito irrevocabile; VELOS supporta entrambi. Evita i trasferimenti anticipati di contanti verso conti sconosciuti e non pagare mai su conti bancari personali. Abbina il piano dei pagamenti alle tappe della consegna, così nessun importo elevato è a rischio in un dato momento.",
  "marketplace-dd-s3-title": "3. Verifica la merce",
  "marketplace-dd-s3-body": "Prima di contrattare, richiedi certificati di analisi, specifiche di qualità e, dove pertinente, documenti di origine. Usa un’ispezione pre-spedizione (SGS, Bureau Veritas o un agente di fiducia) e conserva il diritto di rifiutare la merce non conforme alle specifiche concordate.",
  "marketplace-dd-s4-title": "4. Metti tutto per iscritto",
  "marketplace-dd-s4-body": "Firma un vero contratto di vendita/acquisto: specifica del prodotto, Incoterms 2020, calendario di consegna, condizioni di pagamento, diritti di ispezione, risoluzione delle controversie e legge applicabile. I modelli di documenti di VELOS e la cronologia della negoziazione possono supportarti, ma non sostituiscono la tua verifica legale.",
  "marketplace-dd-s5-title": "5. Rispetta le norme di conformità",
  "marketplace-dd-s5-body": "Le liste di sanzioni (UN, EU, OFAC), i controlli sulle esportazioni, i beni a doppio uso, gli obblighi AML/KYC e le norme doganali si applicano a te personalmente e alla tua azienda. È tua responsabilità — non di VELOS — garantire che uno scambio pianificato sia legale per entrambe le parti.",
  "marketplace-dd-s6-title": "6. Segnala attività sospette",
  "marketplace-dd-s6-body": "Se un annuncio sembra fraudolento, ingannevole o vietato, segnalalo con il pulsante Segnala presente nell’annuncio. Il nostro team esamina ogni segnalazione. Se un affare è già andato storto, contatta subito la tua banca e coinvolgi le forze dell’ordine della tua giurisdizione — VELOS può supportare le indagini con i dati che detiene legittimamente.",
  "marketplace-locked-tier-title": "La comunicazione è bloccata al tuo livello",
  "marketplace-locked-tier-body": "Tutti possono sfogliare questo marketplace, ma pubblicare, rispondere, negoziare e fare offerte richiede il livello Standard o superiore. Effettua l’upgrade del livello del tuo portale per sbloccare la comunicazione.",
  "marketplace-locked-tier-body-respond": "Rispondere a questo annuncio richiede il livello Standard o superiore. Effettua l’upgrade del livello del tuo portale per inviare offerte.",
  "marketplace-locked-tier-body-negotiate": "Inviare messaggi o offerte richiede il livello Standard o superiore. Effettua l’upgrade del livello del tuo portale per continuare a negoziare.",
  "marketplace-locked-tier-body-bid": "Fare offerte d’asta richiede il livello Standard o superiore. Effettua l’upgrade del livello del tuo portale per partecipare alle aste.",
  "marketplace-locked-tier-body-qa": "Porre o rispondere a domande richiede il livello Standard o superiore. Effettua l’upgrade del livello del tuo portale per partecipare alla discussione.",
  "marketplace-locked-kyc-title": "È richiesta la verifica KYC",
  "marketplace-locked-kyc-body": "Per comunicare sul marketplace, la tua revisione KYC deve essere pienamente approvata — identità, azienda e documenti bancari verificati. Completa o attendi la tua revisione KYC per sbloccare pubblicazione, risposte e offerte.",
  "marketplace-locked-kyc-body-respond": "La tua revisione KYC deve essere pienamente approvata prima di poter rispondere agli annunci. Completa o attendi la tua revisione KYC.",
  "marketplace-locked-kyc-body-negotiate": "La tua revisione KYC deve essere pienamente approvata prima di poter inviare messaggi o offerte. Completa o attendi la tua revisione KYC.",
  "marketplace-locked-kyc-body-bid": "La tua revisione KYC deve essere pienamente approvata prima di poter fare offerte. Completa o attendi la tua revisione KYC.",
  "marketplace-locked-kyc-body-qa": "La tua revisione KYC deve essere pienamente approvata prima di poter porre o rispondere a domande. Completa o attendi la tua revisione KYC.",
  "marketplace-locked-upgrade-cta": "Richiedi upgrade del livello",
  "marketplace-locked-kyc-cta": "Vai alla verifica KYC",
  "marketplace-dd-form-note": "VELOS mette in contatto gli operatori commerciali ma non è parte del tuo affare — verifica la controparte, concorda un pagamento sicuro (escrow/lettera di credito) e metti i termini per iscritto prima di impegnarti.",
